import pty, os, sys, time, select, fcntl, termios, struct, signal, json

class Session:
    def __init__(self, cmd, env, rows=10, cols=40):
        self.master, slave = pty.openpty()
        fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0,0))
        self.rows=rows; self.cols=cols
        pid=os.fork()
        if pid==0:
            try:
                os.close(self.master)
                os.setsid()
                fcntl.ioctl(slave, termios.TIOCSCTTY, 0)
                os.dup2(slave,0); os.dup2(slave,1); os.dup2(slave,2)
                if slave>2: os.close(slave)
                # build clean env
                e={"PATH": os.environ.get("PATH","/usr/bin:/bin"), "HOME": os.environ.get("HOME","/home/agent"), "TERM":"xterm-256color", "LANG":"C.UTF-8", "LC_ALL":"C.UTF-8"}
                e.update(env)
                # values None delete
                e={k:v for k,v in e.items() if v is not None}
                os.execvpe(cmd[0], cmd, e)
            except Exception as ex:
                print("exec err",ex, file=sys.stderr); os._exit(127)
        self.pid=pid
        os.close(slave)
        self.out=b""
        self.mark=0
    def read_dur(self,dur=0.8):
        end=time.time()+dur
        while time.time()<end:
            r,_,_=select.select([self.master],[],[],0.05)
            if r:
                try: data=os.read(self.master,65536)
                except OSError: break
                if not data: break
                self.out+=data
    def snapshot(self,label):
        print(f"---{label}---")
        chunk=self.out[self.mark:]; self.mark=len(self.out)
        print(repr(chunk))
        print(chunk.decode(errors='backslashreplace'))
    def send(self,data):
        os.write(self.master, data if isinstance(data,bytes) else data.encode())
    def wait_nohang(self):
        return os.waitpid(self.pid, os.WNOHANG)
    def wait(self,timeout=3):
        end=time.time()+timeout
        while time.time()<end:
            w=os.waitpid(self.pid, os.WNOHANG)
            if w[0]: return os.waitstatus_to_exitcode(w[1])
            self.read_dur(0.1)
        return None

