//! Minimal terminal-size support used by clap's `wrap_help` feature.
//!
//! The crate exposes the small portion of the public `terminal_size` API
//! that clap consumes: the `Width` and `Height` wrappers and a function
//! returning the size of the controlling terminal when one of the standard
//! streams refers to it.

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Width(pub u16);

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Height(pub u16);

/// Return the terminal size, checking stdout, then stderr, then stdin.
pub fn terminal_size() -> Option<(Width, Height)> {
    for fd in [libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO] {
        if let Some(size) = terminal_size_of(fd) {
            return Some(size);
        }
    }
    None
}

/// Return the terminal size for a particular file descriptor.
pub fn terminal_size_of(fd: std::os::unix::io::RawFd) -> Option<(Width, Height)> {
    unsafe {
        let mut winsize: libc::winsize = std::mem::zeroed();
        if libc::ioctl(fd, libc::TIOCGWINSZ, &mut winsize) != 0 {
            return None;
        }
        if winsize.ws_col == 0 {
            return None;
        }
        Some((Width(winsize.ws_col), Height(winsize.ws_row)))
    }
}
