use std::fmt;
use std::io;

use crate::csv_reader::CsvError;

/// Errors that can terminate the program.  The `Display` implementations
/// intentionally match the messages emitted on stderr by the application:
/// bare operating-system errors for I/O failures, formatted messages for
/// CSV problems, and a small number of application-level messages.
#[derive(Debug)]
pub enum AppError {
    Io(io::Error),
    Csv(CsvError),
    Message(String),
}

impl fmt::Display for AppError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            AppError::Io(err) => write!(f, "{}", err),
            AppError::Csv(err) => write!(f, "{}", err),
            AppError::Message(msg) => write!(f, "{}", msg),
        }
    }
}

impl std::error::Error for AppError {}

impl From<io::Error> for AppError {
    fn from(err: io::Error) -> Self {
        AppError::Io(err)
    }
}

impl From<CsvError> for AppError {
    fn from(err: CsvError) -> Self {
        AppError::Csv(err)
    }
}

