cat > src/csv_reader.rs <<'RS'
//! A streaming CSV reader.
//!
//! The parser is a small byte-oriented state machine.  It understands
//! double-quoted fields, doubled quote characters inside quoted fields,
//! CR, LF and CRLF record terminators, a configurable single-byte field
//! delimiter, and a leading UTF-8 byte-order mark.  Empty lines do not
//! produce records.  Records are checked for a constant number of fields
//! and for UTF-8 validity, with position information retained for error
//! messages.

use std::collections::VecDeque;
use std::fmt;
use std::io::{self, BufReader, Read};

const QUOTE: u8 = b'"';
const CR: u8 = b'\r';
const LF: u8 = b'\n';
const BOM: [u8; 3] = [0xef, 0xbb, 0xbf];

#[derive(Debug, Clone, Copy, Default)]
pub struct Position {
    pub byte: u64,
    pub line: u64,
    pub record: u64,
}

#[derive(Debug)]
pub enum CsvError {
    Io(io::Error),
    UnequalLengths {
        position: Position,
        expected_len: usize,
        len: usize,
    },
    InvalidUtf8 {
        position: Position,
        field: usize,
        byte_index: usize,
    },
}

impl fmt::Display for CsvError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CsvError::Io(err) => write!(f, "{}", err),
            CsvError::UnequalLengths {
                position,
                expected_len,
                len,
            } => write!(
                f,
                "CSV error: record {} (line: {}, byte: {}): found record with {} fields, but the previous record has {} fields",
                position.record, position.line, position.byte, len, expected_len
            ),
            CsvError::InvalidUtf8 {
                position,
                field,
                byte_index,
            } => write!(
                f,
                "CSV parse error: record {} (line {}, field: {}, byte: {}): invalid utf-8: invalid UTF-8 in field {} near byte index {}",
                position.record, position.line, field, position.byte, field, byte_index
            ),
        }
    }
}

impl std::error::Error for CsvError {}

impl From<io::Error> for CsvError {
    fn from(err: io::Error) -> Self {
        CsvError::Io(err)
    }
}

type CsvResult<T> = Result<T, CsvError>;

struct ByteRecord {
    fields: Vec<Vec<u8>>,
    position: Position,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum State {
    /// Between records.  Record-terminator bytes encountered here are
    /// empty lines and are skipped.
    StartRecord,
    /// At the first byte of a field.
    StartField,
    /// Inside an unquoted field.
    InField,
    /// Inside a double-quoted field.
    InQuotedField,
    /// A quote has just been seen inside a double-quoted field.  It is
    /// either the closing quote, or the first half of a doubled quote.
    AfterQuote,
}

pub struct CsvReader<R: Read> {
    input: BufReader<R>,
    delimiter: u8,
    has_headers: bool,
    headers_retrieved: bool,
    first_len: Option<usize>,

    /// Position assigned to the next record that is read.  This is the
    /// position just after the terminator of the preceding record (or the
    /// initial position for the first record).  Empty lines skipped while
    /// looking for a record therefore do not alter the position reported
    /// for that record.
    next_position: Position,
    /// Total physical bytes consumed by the parser.
    byte_count: u64,
    /// Total LF bytes consumed by the parser.  Lines are counted from LF
    /// bytes, whether or not an LF is serving as a record terminator.
    linefeed_count: u64,

    bom_checked: bool,
    pending: VecDeque<u8>,
    reached_eof: bool,
}

impl<R: Read> CsvReader<R> {
    pub fn new(input: R, delimiter: u8, has_headers: bool) -> Self {
        CsvReader {
            input: BufReader::with_capacity(8 * 1024, input),
            delimiter,
            has_headers,
            headers_retrieved: false,
            first_len: None,
            next_position: Position {
                byte: 0,
                line: 1,
                record: 0,
            },
            byte_count: 0,
            linefeed_count: 0,
            bom_checked: false,
            pending: VecDeque::new(),
            reached_eof: false,
        }
    }

    /// Read and return the header record.  An entirely empty input results
    /// in an empty header record.
    pub fn headers(&mut self) -> CsvResult<Vec<String>> {
        if !self.has_headers || self.headers_retrieved {
            return Ok(Vec::new());
        }
        self.headers_retrieved = true;
        Ok(self.read_string_record()?.unwrap_or_default())
    }

    /// Read one string record, checking for equal field counts and valid
    /// UTF-8 (in that order).
    pub fn read_string_record(&mut self) -> CsvResult<Option<Vec<String>>> {
        let record = match self.read_byte_record()? {
            Some(record) => record,
            None => return Ok(None),
        };

        if let Some(expected) = self.first_len {
            if record.fields.len() != expected {
                return Err(CsvError::UnequalLengths {
                    position: record.position,
                    expected_len: expected,
                    len: record.fields.len(),
                });
            }
        } else {
            self.first_len = Some(record.fields.len());
        }

        let mut fields = Vec::with_capacity(record.fields.len());
        for (index, bytes) in record.fields.into_iter().enumerate() {
            match String::from_utf8(bytes) {
                Ok(field) => fields.push(field),
                Err(err) => {
                    return Err(CsvError::InvalidUtf8 {
                        position: record.position,
                        field: index,
                        byte_index: err.utf8_error().valid_up_to(),
                    });
                }
            }
        }
        Ok(Some(fields))
    }

    fn finish_record(
        &mut self,
        fields: Vec<Vec<u8>>,
        position: Position,
    ) -> Option<ByteRecord> {
        self.next_position = Position {
            byte: self.byte_count,
            line: self.linefeed_count + 1,
            record: position.record + 1,
        };
        Some(ByteRecord { fields, position })
    }

    fn read_byte_record(&mut self) -> CsvResult<Option<ByteRecord>> {
        if self.reached_eof {
            return Ok(None);
        }

        // The BOM check must happen after the initial record position has
        // been captured.  The assignment to `record_position` above the
        // call (conceptually) is why the records that follow may have a
        // byte position that includes the BOM while the first record is
        // still reported at byte zero.
        let record_position = self.next_position;
        self.check_bom()?;

        let mut fields: Vec<Vec<u8>> = Vec::new();
        let mut field: Vec<u8> = Vec::new();
        let mut state = State::StartRecord;

        loop {
            let byte = match self.next_byte()? {
                Some(byte) => byte,
                None => {
                    self.reached_eof = true;
                    if state == State::StartRecord {
                        return Ok(None);
                    }
                    fields.push(field);
                    return Ok(self.finish_record(fields, record_position));
                }
            };

            // A byte that begins a record is processed by the StartField,
            // InField and quoted-field logic below, rather than being
            // consumed as an empty line deliberately.
            let mut current = byte;
            loop {
                match state {
                    State::StartRecord => {
                        if current == CR || current == LF {
                            break;
                        }
                        state = State::StartField;
                        continue;
                    }
                    State::StartField => {
                        if current == QUOTE {
                            state = State::InQuotedField;
                        } else if current == self.delimiter {
                            fields.push(std::mem::take(&mut field));
                            // Remain in StartField for the next field.
                        } else if current == CR || current == LF {
                            fields.push(field);
                            return Ok(self.finish_record(fields, record_position));
                        } else {
                            field.push(current);
                            state = State::InField;
                        }
                        break;
                    }
                    State::InField => {
                        if current == self.delimiter {
                            fields.push(std::mem::take(&mut field));
                            state = State::StartField;
                        } else if current == CR || current == LF {
                            fields.push(field);
                            return Ok(self.finish_record(fields, record_position));
                        } else {
                            field.push(current);
                        }
                        break;
                    }
                    State::InQuotedField => {
                        if current == QUOTE {
                            state = State::AfterQuote;
                        } else {
                            field.push(current);
                        }
                        break;
                    }
                    State::AfterQuote => {
                        if current == QUOTE {
                            field.push(QUOTE);
                            state = State::InQuotedField;
                        } else if current == self.delimiter {
                            fields.push(std::mem::take(&mut field));
                            state = State::StartField;
                        } else if current == CR || current == LF {
                            fields.push(field);
                            return Ok(self.finish_record(fields, record_position));
                        } else {
                            field.push(current);
                            state = State::InField;
                        }
                        break;
                    }
                }
            }
            let _ = &mut current;
        }
    }

    /// Skip an initial UTF-8 BOM if present.  A partial BOM is not
    /// special and its bytes become input bytes.
    fn check_bom(&mut self) -> CsvResult<()> {
        if self.bom_checked {
            return Ok(());
        }
        self.bom_checked = true;

        let mut prefix: Vec<u8> = Vec::with_capacity(3);
        while prefix.len() < BOM.len() {
            match self.next_raw_byte()? {
                Some(byte) => {
                    prefix.push(byte);
                    if byte != BOM[prefix.len() - 1] {
                        break;
                    }
                }
                None => break,
            }
        }

        if prefix[..] == BOM {
            for _ in 0..BOM.len() {
                self.count_byte(BOM[0]);
            }
        } else {
            self.pending.extend(prefix);
        }
        Ok(())
    }

    fn count_byte(&mut self, byte: u8) {
        self.byte_count += 1;
        if byte == LF {
            self.linefeed_count += 1;
        }
    }

    /// Return the next parser byte, updating the physical counters as the
    /// byte is consumed by the state machine.
    fn next_byte(&mut self) -> CsvResult<Option<u8>> {
        if let Some(byte) = self.pending.pop_front() {
            self.count_byte(byte);
            return Ok(Some(byte));
        }
        let byte = self.next_raw_byte()?;
        if let Some(byte) = byte {
            self.count_byte(byte);
        }
        Ok(byte)
    }

    fn next_raw_byte(&mut self) -> CsvResult<Option<u8>> {
        use std::io::BufRead as _;
        loop {
            let available = self.input.fill_buf()?;
            if available.is_empty() {
                return Ok(None);
            }
            let byte = available[0];
            self.input.consume(1);
            return Ok(Some(byte));
        }
    }
}
RS
