            input: BufReader::with_capacity(8 * 1024, input),
            delimiter,
            has_headers,
            headers_retrieved: false,
            first_len: None,
            next_position: Position {
                byte: 0,
                line: 1,
                record: 0,
            },
            byte_count: 0,
            linefeed_count: 0,
            bom_checked: false,
            pending: VecDeque::new(),
            reached_eof: false,
        }
    }

