//! Streaming table printer.

pub mod row;
pub mod style;

use std::collections::VecDeque;
use std::io::{self, Read, Write};

use unicode_truncate::Alignment;

use crate::csv_reader::{CsvError, CsvReader};
use crate::error::AppError;

pub use style::Style;

#[derive(Debug, Clone, Copy)]
pub struct TableOptions {
    pub style: Style,
    pub padding: usize,
    pub indent: usize,
    pub header_align: Alignment,
    pub body_align: Alignment,
    pub number: bool,
}

/// Records available to the printer after width sniffing: the buffered
/// records first, followed by any records still to be read.  A one-item
/// lookahead is retained because some border lines are only printed when
/// another item (including an error item) follows the current row.
struct RecordSource<R: Read> {
    buffered: VecDeque<Vec<String>>,
    reader: CsvReader<R>,
    peeked: Option<Option<Result<Vec<String>, CsvError>>>,
    finished: bool,
}

impl<R: Read> RecordSource<R> {
    fn new(buffered: Vec<Vec<String>>, reader: CsvReader<R>) -> Self {
        RecordSource {
            buffered: buffered.into(),
            reader,
            peeked: None,
            finished: false,
        }
    }

    fn next_item(&mut self) -> Option<Result<Vec<String>, CsvError>> {
        if let Some(item) = self.peeked.take() {
            return item;
        }
        if let Some(record) = self.buffered.pop_front() {
            return Some(Ok(record));
        }
        if self.finished {
            return None;
        }
        match self.reader.read_string_record() {
            Ok(Some(record)) => Some(Ok(record)),
            Ok(None) => {
                self.finished = true;
                None
            }
            Err(err) => {
                self.finished = true;
                Some(Err(err))
            }
        }
    }

    fn peek_is_some(&mut self) -> bool {
        if self.peeked.is_none() {
            self.peeked = Some(self.next_item());
        }
        matches!(self.peeked, Some(Some(_)))
    }
}

fn with_line_number(record: Vec<String>, line_number: Option<usize>) -> Vec<String> {
    match line_number {
        Some(number) => {
            let mut cells = Vec::with_capacity(record.len() + 1);
            cells.push(number.to_string());
            cells.extend(record);
            cells
        }
        None => record,
    }
}

pub fn write_table<W: Write, R: Read>(
    writer: &mut W,
    headers: Option<Vec<String>>,
    buffered: Vec<Vec<String>>,
    reader: CsvReader<R>,
    widths: &[usize],
    options: TableOptions,
) -> Result<(), AppError> {
    let borders = options.style.borders();
    let mut source = RecordSource::new(buffered, reader);

    style::write_border_line(writer, borders.top, widths, options.padding, options.indent)?;

    if let Some(headers) = headers {
        let header_cells = if options.number {
            let mut cells = Vec::with_capacity(headers.len() + 1);
            cells.push("#".to_owned());
            cells.extend(headers);
            cells
        } else {
            headers
        };
        row::write_row(
            writer,
            &header_cells,
            widths,
            &borders,
            options.padding,
            options.indent,
            options.header_align,
        )?;
        if source.peek_is_some() {
            style::write_border_line(
                writer,
                borders.middle,
                widths,
                options.padding,
                options.indent,
            )?;
        }
    }

    let mut line_number = 1usize;
    while let Some(item) = source.next_item() {
        let record = item?;
        let cells = with_line_number(
            record,
            if options.number {
                Some(line_number)
            } else {
                None
            },
        );
        line_number += 1;
        row::write_row(
            writer,
            &cells,
            widths,
            &borders,
            options.padding,
            options.indent,
            options.body_align,
        )?;
        if options.style.is_grid() && source.peek_is_some() {
            style::write_border_line(
                writer,
                borders.middle,
                widths,
                options.padding,
                options.indent,
            )?;
        }
    }

    style::write_border_line(
        writer,
        borders.bottom,
        widths,
        options.padding,
        options.indent,
    )?;
    Ok(())
}
