cat > src/pager.rs <<'RS'
//! Optional paging through an external `less` process.
//!
//! When stdout is a terminal, paging is implemented by forking.  The
//! original process image is replaced by `less` and receives the table
//! on its standard input; the forked process continues as the table
//! writer.  This keeps the pager as the process observed by the calling
//! shell.  If no usable `less` executable is available, output simply
//! remains on the terminal.

use std::ffi::{CStr, OsStr};
use std::io::{self, IsTerminal};
use std::os::unix::ffi::OsStrExt;
use std::path::{Path, PathBuf};

fn is_executable_file(path: &Path) -> bool {
    let bytes = path.as_os_str().as_bytes();
    if bytes.contains(&0) {
        return false;
    }
    let mut path_bytes = bytes.to_vec();
    path_bytes.push(0);
    let metadata = match std::fs::metadata(path) {
        Ok(metadata) => metadata,
        Err(_) => return false,
    };
    if !metadata.is_file() {
        return false;
    }
    unsafe { libc::access(path_bytes.as_ptr() as *const libc::c_char, libc::X_OK) == 0 }
}

fn find_less() -> Option<PathBuf> {
    let candidate = Path::new("less");
    match std::env::var_os("PATH") {
        Some(paths) => {
            for entry in std::env::split_paths(&paths) {
                let path = if entry.as_os_str().is_empty() {
                    candidate.to_path_buf()
                } else {
                    entry.join(candidate)
                };
                if is_executable_file(&path) {
                    return Some(path);
                }
            }
            None
        }
        None => {
            // This mirrors the default search path used by `execvp` when
            // PATH is absent from the environment.
            for directory in ["/bin", "/usr/bin"] {
                let path = Path::new(directory).join(candidate);
                if is_executable_file(&path) {
                    return Some(path);
                }
            }
            None
        }
    }
}

pub fn setup_pager() {
