/// Re-create the grouped usage line for an unknown-long-argument error.
///
/// The command-line arguments form a single logical group (including the
/// positional file argument).  When clap reports an unknown long option
/// after, or suggests, an argument from that group, the usage line shows
/// the whole group rather than the individual arguments that happen to
/// have been supplied.  Help and version are outside the group, so they
/// remain in front of the group when clap includes them in the usage.
fn adjust_unknown_argument_usage(command: &Command, error: &mut clap::Error) {
    if error.kind() != ErrorKind::UnknownArgument {
        return;
    }
    let invalid_arg = match error.get(ContextKind::InvalidArg) {
        Some(ContextValue::String(arg)) if arg.starts_with("--") => arg,
        _ => return,
    };
    let _ = invalid_arg;

    let old_usage = match error.get(ContextKind::Usage) {
        Some(ContextValue::StyledStr(usage)) => usage.to_string(),
        _ => return,
    };
    let after_title = match old_usage.strip_prefix("Usage: ") {
        Some(rest) => rest,
        None => return,
    };

    let bin_name = command
        .get_bin_name()
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| command.get_name());
