import subprocess
# Generate plausible alias candidates from option words and transformations
bases=["no","header","headers","head","number","numbers","num","seq","sequence","index","line","lines","row","rows","tsv","tab","delimiter","delim","separator","sep","style","border","padding","pad","indent","sniff","limit","align","alignment","headeralign","bodyalign","pager","paging","page","less","file","input"]
cands=set(bases)
for a in bases:
 for b in bases:
  cands.add(f"{a}-{b}"); cands.add(f"{a}{b}"); cands.add(f"{a}_{b}")
for a in list(cands):
 cands.add(a+"s")
# abbreviations / prefixes of canonical and candidates length>=2
for a in list(cands):
 for n in range(2,min(len(a),8)):
  cands.add(a[:n])
accepted=[]
for w in sorted(cands):
 r=subprocess.run(["./executable","-P",f"--{w}"],input=b"a,b\n1,2\n",capture_output=True)
 if b"unexpected argument" not in r.stderr:
  accepted.append((w,r.returncode,r.stderr[:100]))
for x in accepted: print(x)
print("tested",len(cands))
PY"}

