{"command":"python3 << 'PY'
import subprocess, itertools, string, re
standard={"--no-headers","--number","--tsv","--delimiter","--style","--padding","--indent","--sniff","--header-align","--body-align","--disable-pager","--help","--version","--seq"}
seen={}
for n in [1,2]:
 for letters in itertools.product(string.ascii_lowercase, repeat=n):
  w=''.join(letters)
  r=subprocess.run(["./executable",f"--{w}"],input=b"a\n",capture_output=True,text=True)
  m=re.search(r"similar argument exists: '(--[^']+)'",r.stderr)
  if m and m.group(1) not in standard:
   seen.setdefault(m.group(1),[]).append(w)
  if b"unexpected argument" not in r.stderr.encode():
   seen.setdefault("ACCEPTED "+w,[]).append(r.stderr)
print(seen)
PY"}

