import re
def parse(path):
    ranges=[]
    for line in open(path):
        m=re.match(r'U\+([0-9A-F]+)\.\.U\+([0-9A-F]+) orig=(\d+) new=(\d+)',line)
        if m:
            ranges.append((int(m.group(1),16),int(m.group(2),16),int(m.group(3))))
    return ranges
sniff=parse('/tmp/unicode_batch.out')
fmt=parse('/tmp/unicode_format.out')
def fmt_ranges(name,ranges):
    out=[f"const {name}: &[(u32, u32, usize)] = &["]
    for lo,hi,w in ranges:
        out.append(f"    (0x{lo:x}, 0x{hi:x}, {w}),")
    out.append("];\n")
    return "\n".join(out)

code='''//! Compatibility adjustments for Unicode width classification.
//!
//! The width tables in current `unicode-width`/`unicode-truncate`
//! releases classify a few hundred code points differently from the
//! tables this program's output is specified against (principally
//! newly-assigned emoji and combining marks, some enclosed/dingbat
//! symbols, and a few unassigned blocks whose default widths changed).
//! The ranges below contain only code points whose single-character
//! width differs; text that does not contain them takes the ordinary
//! library path unchanged.

use std::borrow::Cow;
use std::collections::VecDeque;

use unicode_truncate::{Alignment, UnicodeTruncateStr};
use unicode_width::UnicodeWidthStr;

'''
code+=fmt_ranges("SNIFF_WIDTH_OVERRIDES",sniff)
code+=fmt_ranges("FORMAT_WIDTH_OVERRIDES",fmt)
code+'''fn lookup(ranges: &[(u32, u32, usize)], ch: char) -> Option<usize> {
    let cp = ch as u32;
    let index = ranges.partition_point(|&(start, _, _)| start <= cp);
    if index == 0 {
        return None;
    }
    let (start, end, width) = ranges[index - 1];
    if start <= cp && cp <= end {
        Some(width)
    } else {
        None
    }
}

fn sniff_override(ch: char) -> Option<usize> {
    lookup(SNIFF_WIDTH_OVERRIDES, ch)
}

fn format_override(ch: char) -> Option<usize> {
    lookup(FORMAT_WIDTH_OVERRIDES, ch)
}

/// Width used when sniffing column widths.
pub fn sniff_width(text: &str) -> usize {
    if !text.chars().any(|ch| sniff_override(ch).is_some()) {
        return text.width_cjk();
    }
    let transformed: String = text
        .chars()
        .map(|ch| match sniff_override(ch) {
            Some(0) => '\\u{200b}',
            Some(1) => 'a',
            Some(2) => '\\u{4e2d}',
            _ => ch,
        })
        .collect();
    transformed.width_cjk()
}

fn choose_placeholder(candidates: &[char], text: &str) -> Option<char> {
    candidates.iter().copied().find(|ch| !text.contains(*ch))
}

/// Truncate and pad a cell to `width`, honouring the compatibility
/// widths above for formatting.  This is `unicode_pad` for the great
/// majority of inputs.
pub fn pad_cell<'a>(text: &'a str, width: usize, alignment: Alignment) -> Cow<'a, str> {
    if !text.chars().any(|ch| format_override(ch).is_some()) {
        return text.unicode_pad(width, alignment, true);
    }

    // Replace an affected code point by an otherwise-uninvolved
    // character with the desired ordinary width, let the library do
    // its (sequence-aware) truncation and padding, and then restore
    // the original characters in order.  The placeholder characters
    // are selected so that they do not occur in the original cell.
    let zero = choose_placeholder(
        &[
            '\\u{200b}', '\\u{2060}', '\\u{feff}', '\\u{034f}', '\\u{061c}', '\\u{180e}',
            '\\u{0300}', '\\u{0301}',
        ],
        text,
    );
    let one = choose_placeholder(
        &[
            '\\u{e000}', '\\u{e001}', '\\u{e002}', '\\u{f8ff}', '\\u{100000}', '\\u{10fffd}',
        ],
        text,
    );
    let two = choose_placeholder(
        &[
            '\\u{4e2d}', '\\u{4e2e}', '\\u{4e2f}', '\\u{3042}', '\\u{3044}', '\\u{30a2}',
        ],
        text,
    );

    let mut transformed = String::with_capacity(text.len());
    let mut originals: Vec<(char, VecDeque<char>)> = Vec::new();
    let mut record = |placeholder: char, original: char| {
        if let Some((_, queue)) = originals.iter_mut().find(|(p, _)| *p == placeholder) {
            queue.push_back(original);
        } else {
            originals.push((placeholder, VecDeque::from([original])));
        }
    };

    for ch in text.chars() {
        let placeholder = match format_override(ch) {
            Some(0) => zero,
            Some(1) => one,
            Some(2) => two,
            _ => None,
        };
        match placeholder {
            Some(placeholder) => {
                record(placeholder, ch);
                transformed.push(placeholder);
            }
            None => transformed.push(ch),
        }
    }

    // If a needed placeholder could not be found (a cell containing
    // every candidate above as literal text), fall back to the
    // library behaviour rather than guessing.
    if text.chars().any(|ch| {
        matches!(
            (format_override(ch), zero, one, two),
            (Some(0), None, _, _) | (Some(1), _, None, _) | (Some(2), _, _, None)
        )
    }) {
        return text.unicode_pad(width, alignment, true);
    }

    let padded = transformed.unicode_pad(width, alignment, true);
    let mut restored = String::with_capacity(padded.len());
    for ch in padded.chars() {
        if let Some((_, queue)) = originals.iter_mut().find(|(p, _)| *p == ch) {
            if let Some(original) = queue.pop_front() {
                restored.push(original);
                continue;
            }
        }
        restored.push(ch);
    }
    Cow::Owned(restored)
}
'''
